@extends('admin.layout') @section('title','Roles and permissions') @section('content')<h1>Roles & permissions</h1><p class="text-secondary">Permissions are manual and apply to every branch.</p><div class="row g-4"><div class="col-xl-7"><div class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>Role</th><th>Permissions</th><th>Users</th><th>Action</th></tr></thead><tbody>@foreach($roles as $role)<tr><td>{{ $role->name }}</td><td>{{ $role->permissions->pluck('name')->join(', ') }}</td><td>{{ $role->users_count }}</td><td>@if($role->slug!=='super-admin')<button class="btn btn-sm btn-outline-primary edit-role" data-role="{{ json_encode(['id'=>$role->id,'name'=>$role->name,'slug'=>$role->slug,'permissions'=>$role->permissions->pluck('id')]) }}">Edit</button> <button class="btn btn-sm btn-outline-danger delete-item" data-url="{{ route('admin.roles.delete',$role) }}">Delete</button>@else Protected @endif</td></tr>@endforeach</tbody></table></div></div></div><div class="col-xl-5"><form class="panel ajax-form" method="post" action="{{ route('admin.roles.save') }}">@csrf<h2 id="role-form-title">Add role</h2><input type="hidden" name="id" id="role-id"><label class="form-label" for="role-name">Role name</label><input id="role-name" class="form-control mb-3" name="name" required><label class="form-label" for="role-slug">Slug</label><input id="role-slug" class="form-control mb-3" name="slug" required pattern="[A-Za-z0-9_-]+"><fieldset><legend class="fs-6">Permissions</legend>@foreach($permissions as $permission)<label class="form-check mb-2"><input class="form-check-input role-permission" type="checkbox" name="permissions[]" value="{{ $permission->id }}"> {{ $permission->name }}</label>@endforeach</fieldset><div class="mt-3"><button class="btn btn-primary">Save role</button> <button type="reset" class="btn btn-light reset-role">Clear</button></div></form></div></div>@endsection